import * as T from './vendor/three.module.js';
export function installRiverbend({scene,camera,colliders,pause,rewards,getCurrentSeat=()=>null,getVillagePlaces=()=>[]}){
 const root=new T.Group();root.name='Riverbend riverside preview';scene.add(root);
 const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.85}),stone=mat('#b1aaa0'),wood=mat('#866344'),green=mat('#385e53'),clay=mat('#b77851'),reed=mat('#bda576');
 const part=(g,m,x,y,z)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;root.add(o);return o;};
 const box=(x,y,z,w,h,d,m,solid=false)=>{const o=part(new T.BoxGeometry(w,h,d),m,x,y,z);if(solid)colliders.push({x,z,w:w/2+.25,d:d/2+.25});return o;};
 const water=part(new T.PlaneGeometry(6,42),new T.MeshStandardMaterial({color:'#548e9c',roughness:.24,metalness:.25}),-49,.18,153);water.rotation.x=-Math.PI/2;water.name='Riverbend water';colliders.push({x:-49,z:151.375,w:3.25,d:19.625},{x:-49,z:174.15,w:3.25,d:.1});
 box(-43,.12,153,5,.2,44,stone);box(-33,.1,130,24,.15,3,stone);box(-36,.1,165,16,.15,3,stone);
 for(let i=0;i<22;i++){const z=132+i*2;if(z>170&&z<174)continue;box(-45.6,.55,z,.12,1.1,.12,wood,true);}box(-45.6,.95,151,.12,.12,38,wood,true);
 const rippleMat=new T.MeshStandardMaterial({color:'#a1c8ca',transparent:true,opacity:.35});for(let i=0;i<25;i++)box(-49+Math.sin(i*2)*1.6,.195,134+i*1.55,1.1,.01,.035,rippleMat);
 const boats=[];for(let i=0;i<3;i++){const boat=new T.Group();boat.name='Riverbend lantern boat '+(i+1);root.add(boat);const add=(g,m,x,y,z)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;boat.add(o);return o;};const hull=add(new T.SphereGeometry(1,12,8),wood,0,.35,0);hull.scale.set(.65,.24,1.65);add(new T.BoxGeometry(.09,.8,.09),wood,0,.6,0);const glow=new T.MeshStandardMaterial({color:'#ffdc8d',emissive:'#ffb44a',emissiveIntensity:.75});add(new T.SphereGeometry(.28,12,8),glow,0,1.1,0);const reflection=add(new T.CircleGeometry(.5,16),new T.MeshBasicMaterial({color:'#ffca73',transparent:true,opacity:.12,depthWrite:false}),0,.205,.1);reflection.rotation.x=-Math.PI/2;reflection.scale.set(.7,1.7,1);reflection.castShadow=false;boats.push({boat,glow,reflection,offset:i*Math.PI*2/3});}
 let elapsed=0,active=false,held=false,finished=false;
 const inArea=()=>camera.position.x>=-45&&camera.position.x<=-39&&camera.position.z>=130&&camera.position.z<=175;
 function pose(night=0){for(const b of boats){const angle=b.offset+elapsed/36*Math.PI*2;b.boat.position.set(-49+Math.sin(angle)*1.3,active?Math.sin(elapsed*1.7+b.offset)*.035:0,153+Math.cos(angle)*16);b.boat.rotation.y=Math.atan2(1.3*Math.cos(angle),-16*Math.sin(angle));b.reflection.position.y=.205-b.boat.position.y;b.glow.emissiveIntensity=.55+Number(night)*1.3;b.reflection.material.opacity=.08+Number(night)*.2;}}
 pose();

 box(-41,1,131.7,3,1.8,1,wood,true);for(const x of [-41.8,-40.2]){part(new T.CylinderGeometry(.22,.35,.55,16),clay,x,2.15,131.7);}part(new T.CylinderGeometry(.4,.3,.38,16),reed,-41,2.05,131.7);
 box(-43,.6,143,.8,.2,2.8,wood,true);box(-42.65,1.05,143,.12,.9,2.8,wood);const seats=[{name:'Riverbend lantern-boat viewing bench',x:-43,z:143,y:1.5,yaw:Math.PI/2,approach:{x:-41.5,z:143},kind:'riverbend'}];
 function sign(text,x,y,z,w,h){const c=document.createElement('canvas');c.width=Math.round(w*160);c.height=Math.round(h*160);const ctx=c.getContext('2d');ctx.fillStyle='#315a4a';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#fff0c8';ctx.textAlign='center';ctx.textBaseline='middle';let size=c.height*.5;ctx.font=size+'px Georgia';size*=Math.min(1,c.width*.92/ctx.measureText(text).width);ctx.font=size+'px Georgia';ctx.fillText(text,c.width/2,c.height/2);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;part(new T.PlaneGeometry(w,h),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}),x,y,z);}
 sign('RIVERBEND RIVERSIDE',-41,3.1,131.9,6,.8);
 const boardPoint={x:-41,z:133.5,name:'Riverbend riverside discovery display'};const near=()=>Math.hypot(camera.position.x-boardPoint.x,camera.position.z-boardPoint.z)<1.5;
 const canRead=()=>near()||seats.includes(getCurrentSeat());
 const dialog=document.createElement('dialog');dialog.id='riverbendMenu';dialog.setAttribute('aria-labelledby','riverbendTitle');const title=document.createElement('h2');title.id='riverbendTitle';title.textContent='Riverbend Riverside';const intro=document.createElement('p');intro.textContent='The original Riverbend village description celebrates a gently flowing river, fishing and agriculture, lantern boats at its annual River Festival, pottery and woven baskets. This small riverside preview and its location are a new interpretation; three cottages are now open nearby, with a short lantern-boat preview inspired by the annual festival.';const story=document.createElement('p');story.id='riverbendStory';story.setAttribute('role','status');const status=document.createElement('p');status.id='riverbendStatus';const actions=document.createElement('div');const topics=[['festival','River Festival','The original village celebrates an annual River Festival with lantern-adorned boats lighting the river at night. Try the optional 36-second lantern-boat preview here. It is a local scenic animation, not a scheduled community event.'],['crafts','Pottery and baskets','Riverbend’s craftspeople make pottery and woven baskets for markets and festivals. Look for the earthenware vessels and basket at this display.'],['river','Life beside the river','Fishing and agriculture support Riverbend in the original description, alongside cobblestone streets and cottages. Three cottages are now open along the northern lane.']];for(const [id,label,text]of topics){const b=document.createElement('button');b.id='riverbendTopic-'+id;b.textContent=label;b.onclick=()=>{if(!canRead()||!dialog.open)return;story.textContent=text;rewards.completeRiverbend();refresh();};actions.append(b);}const reward=document.createElement('button');reward.id='riverbendRewards';reward.textContent='Find riverside rewards';reward.onclick=()=>{if(!canRead()||!dialog.open)return;pause();rewards.guideTo('riverbend');dialog.close();};const close=document.createElement('button');close.id='riverbendClose';close.textContent='Return to the riverside';close.onclick=()=>dialog.close();dialog.append(title,intro,actions,story,status,reward,close);document.body.append(dialog);const css=document.createElement('link');css.rel='stylesheet';css.href='riverbend.css';document.head.append(css);
 const previewNote=document.createElement('p');previewNote.textContent='Lantern-boat preview · 36 seconds. Watch from the bank or viewing bench. Night view makes the lanterns brighter. This scenic preview does not add points.';
 const startButton=document.createElement('button');startButton.id='riverFestivalStart';startButton.textContent='Start lantern-boat preview';startButton.onclick=()=>{if(!canRead()||!dialog.open)return;start();};
 const benchButton=document.createElement('button');benchButton.id='riverFestivalBench';benchButton.textContent='Find the river viewing bench';benchButton.onclick=()=>{if(!canRead()||!dialog.open)return;pause();rewards.guideToPoint({...seats[0].approach,name:seats[0].name});dialog.close();};dialog.append(previewNote,startButton,benchButton);
 const villageLinks=document.createElement('details');villageLinks.id='riverbendVillageLinks';const villageSummary=document.createElement('summary');villageSummary.textContent='Explore the village';const villageList=document.createElement('div');villageLinks.append(villageSummary,villageList);dialog.append(villageLinks);
 function refreshVillageLinks(){villageLinks.open=false;villageList.replaceChildren();for(const point of getVillagePlaces()){const button=document.createElement('button');button.id='riverbendWalk-'+point.id;button.textContent='Walk to '+point.name;button.onclick=()=>{if(!canRead()||!dialog.open)return;pause();rewards.guideToPoint({x:point.x,z:point.z,name:point.name});dialog.close();};villageList.append(button);}villageLinks.hidden=villageList.children.length===0;}
 const dock=document.createElement('div');dock.id='riverFestival';dock.hidden=true;const label=document.createElement('span');label.id='riverFestivalStatus';const hold=document.createElement('button');hold.id='riverFestivalPause';hold.textContent='Pause';hold.onclick=()=>{if(active){held=!held;hold.textContent=held?'Resume':'Pause';}};const stop=document.createElement('button');stop.id='riverFestivalStop';stop.textContent='Stop';stop.onclick=()=>{active=false;held=false;finished=false;elapsed=0;pose(lastNight);dock.hidden=true;};dock.append(label,hold,stop);document.body.append(dock);let lastNight=0;
 function start(){if(active||!inArea())return false;pause();elapsed=0;active=true;held=false;finished=false;dialog.close();hold.hidden=false;hold.textContent='Pause';stop.textContent='Stop';dock.hidden=false;pose(lastNight);label.textContent='Lantern boats · 36s';return true;}
 function update(dt,blocked=false,night=0){lastNight=night;if((active||finished)&&!inArea()){stop.onclick();return;}if(active&&!held&&!blocked){elapsed=Math.min(36,elapsed+Math.max(0,Math.min(dt,.1)));if(elapsed>=36){active=false;finished=true;hold.hidden=true;stop.textContent='Dismiss';}}pose(night);dock.hidden=blocked||(!active&&!finished);if(active)label.textContent=(held||blocked?'Paused · ':'Lantern boats · ')+Math.ceil(36-elapsed)+'s';else if(finished)label.textContent='Preview finished · Visit the display to replay';}
 function refresh(){const st=rewards.state();status.textContent=st.claims.includes('riverbend:task')?'Your Riverbend discovery reward is collected.':st.done.includes('riverbend-board')?'Story explored · 20 task points are ready at the Riverbend rewards station.':'Explore one story to unlock 20 task points.';if(!st.saved)status.textContent+=' Progress lasts for this visit only.';}
 return {seats,boardPoint,start,update,state:()=>({active,paused:held,elapsed,finished}),get near(){return near()},get isOpen(){return dialog.open},open(){if(!canRead()||dialog.open)return false;pause();story.textContent='Choose a Riverbend story to explore.';refresh();refreshVillageLinks();dialog.showModal();return true;}};
}
